@@ -0,0 +1,94 @@
+#include "HomeSnapshot.hpp"
+
+#include <nlohmann/json.hpp>
+
+namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {
+
+using nlohmann::json;
+
+const char* to_string(ProjectStatusKind kind)
+{
+    switch (kind) {
+    case ProjectStatusKind::Draft: return "draft";
+    case ProjectStatusKind::Sliced: return "sliced";
+    case ProjectStatusKind::Printing: return "printing";
+    case ProjectStatusKind::Completed: return "completed";
+    case ProjectStatusKind::Unknown: break;
+    }
+    return "unknown";
+}
+
+const char* to_string(PrinterState state)
+{
+    switch (state) {
+    case PrinterState::Printing: return "printing";
+    case PrinterState::Offline: return "offline";
+    case PrinterState::Idle: break;
+    }
+    return "idle";
+}
+
+namespace {
+
+void set_if_present(json& target, const char* key, const std::string& value)
+{
+    if (!value.empty())
+        target[key] = value;
+}
+
+json project_json(const ProjectEntry& project)
+{
+    json out{
+        {"id", project.id},
+        {"name", project.name},
+        {"path", project.path},
+        {"status", json{{"kind", to_string(project.status_kind)}, {"text", project.status_text}}},
+    };
+    set_if_present(out, "thumbnailUrl", project.thumbnail_url);
+    return out;
+}
+
+json printer_json(const PrinterEntry& printer)
+{
+    json spools = json::array();
+    for (const SpoolEntry& spool : printer.spools)
+        spools.push_back(json{{"colour", spool.colour}});
+
+    json out{
+        {"id", printer.id},
+        {"name", printer.name},
+        {"state", to_string(printer.state)},
+        {"spools", std::move(spools)},
+        {"canLaunchMonitor", printer.can_launch_monitor},
+    };
+    set_if_present(out, "statusText", printer.status_text);
+    set_if_present(out, "connectionText", printer.connection_text);
+    set_if_present(out, "nozzleText", printer.nozzle_text);
+    set_if_present(out, "materialLabel", printer.material_label);
+    // A bar belongs to a running job; a finished or idle printer sends none
+    // rather than a zero-width one.
+    if (printer.state == PrinterState::Printing && printer.progress_percent >= 0)
+        out["progressPercent"] = printer.progress_percent;
+    return out;
+}
+
+} // namespace
+
+json state_payload(const Snapshot& snapshot)
+{
+    json projects = json::array();
+    for (const ProjectEntry& project : snapshot.projects)
+        projects.push_back(project_json(project));
+
+    json printers = json::array();
+    for (const PrinterEntry& printer : snapshot.printers)
+        printers.push_back(printer_json(printer));
+
+    return json{
+        {"appearance", snapshot.dark ? "dark" : "light"},
+        {"projects", std::move(projects)},
+        {"printers", std::move(printers)},
+    };
+}
+
+}}}} // namespace Slic3r::GUI::JusPrin::Home
diff --git a/src/slic3r/GUI/JusPrin/Home/HomeSnapshot.hpp b/src/slic3r/GUI/JusPrin/Home/HomeSnapshot.hpp
new file mode 100644
index 0000000000..f9fd9cd80e
--- /dev/null
+++ b/src/slic3r/GUI/JusPrin/Home/HomeSnapshot.hpp
@@ -0,0 +1,73 @@
+#pragma once
+
+// The data behind the Home page, and the one function that turns it into the
+// `state` payload of the jusprin-home-bridge protocol. No wx and no Orca types
+// appear here, so the payload's shape is testable without a GUI: everything
+// that needs a MainFrame, a PresetBundle, or the device layer lives in
+// HomeHost, which fills these structs and hands them over.
+//
+// Optional fields are omitted from the JSON rather than sent as null or as an
+// empty string: the page distinguishes "the host has nothing to say" from "the
+// host says it is empty", and a serialised null would read as the latter.
+
+#include <nlohmann/json_fwd.hpp>
+
+#include <string>
+#include <vector>
+
+namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {
+
+// Matches ProjectStatusKind in the page's protocol.ts. 'unknown' is what the
+// host sends while nothing in the codebase records per-project slice state:
+// the text carries what can be derived instead, and only 'printing' earns a
+// colored dot on the card.
+enum class ProjectStatusKind { Unknown, Draft, Sliced, Printing, Completed };
+
+const char* to_string(ProjectStatusKind kind);
+
+struct ProjectEntry
+{
+    std::string        id;
+    std::string        name;
+    std::string        path;
+    std::string        thumbnail_url; // empty when the .3mf carries none
+    ProjectStatusKind  status_kind{ProjectStatusKind::Unknown};
+    std::string        status_text;
+};
+
+struct SpoolEntry
+{
+    std::string colour; // '#RRGGBB'
+};
+
+enum class PrinterState { Idle, Printing, Offline };
+
+const char* to_string(PrinterState state);
+
+struct PrinterEntry
+{
+    std::string             id;
+    std::string             name;
+    PrinterState            state{PrinterState::Idle};
+    std::string             status_text;
+    // Below zero whenever there is no job to report; only a printing printer
+    // sends a bar.
+    int                     progress_percent{-1};
+    std::string             connection_text;
+    std::string             nozzle_text;
+    std::string             material_label;
+    std::vector<SpoolEntry> spools;
+    bool                    can_launch_monitor{false};
+};
+
+struct Snapshot
+{
+    bool                      dark{false};
+    std::vector<ProjectEntry> projects;
+    std::vector<PrinterEntry> printers;
+};
+
+// The `state` payload: { appearance, projects, printers }.
+nlohmann::json state_payload(const Snapshot& snapshot);
+
+}}}} // namespace Slic3r::GUI::JusPrin::Home
